namespace App\Models;

use App\Core\Database;use App\Core\TurkeyLocation;use PDO;use RuntimeException;use Throwable;
final class CoachProfile
{
    public const INTENTS=['showcase','looking_for_team','open_to_offers'];
    public const TITLES=['Teknik Direktör','Antrenör','Yardımcı Antrenör','Kaleci Antrenörü','Kondisyoner','Analist'];
    public static function validateInput(array $data): array
    {
        $errors=[];$province=trim((string)($data['province']??''));$district=trim((string)($data['district']??''));$title=trim((string)($data['public_title']??'Teknik Direktör'));$intent=trim((string)($data['intent']??'showcase'));
        if($province===''||TurkeyLocation::canonicalProvince($province)===null)$errors['province']='Geçerli bir il seç.';elseif($district===''||!TurkeyLocation::isValidPair($province,$district))$errors['district']='Seçtiğin ilçe bu ile ait değil.';
        if($title===''||self::length($title)>100)$errors['public_title']='Unvan 1-100 karakter olmalı.';if(!in_array($intent,self::INTENTS,true))$errors['intent']='Çalışma durumu geçersiz.';
        if(self::length(trim((string)($data['license_level']??'')))>120)$errors['license_level']='Lisans seviyesi çok uzun.';if(self::length(trim((string)($data['bio']??'')))>1600)$errors['bio']='Biyografi en fazla 1600 karakter olabilir.';if(self::length(trim((string)($data['achievements_text']??'')))>1200)$errors['achievements_text']='Başarılar en fazla 1200 karakter olabilir.';
        if(count(self::normalizeList($data['specialties']??[]))>12)$errors['specialties']='En fazla 12 uzmanlık alanı ekleyebilirsin.';if(count(self::normalizeList($data['formations']??[]))>12)$errors['formations']='En fazla 12 diziliş ekleyebilirsin.';
        return $errors;
    }
    public static function normalizeList(mixed $value): array{if(is_string($value))$value=array_values(array_filter(array_map('trim',explode(',',$value))));if(!is_array($value))return[];$out=[];foreach($value as $v){$v=trim((string)$v);if($v!==''&&!in_array($v,$out,true))$out[]=$v;}return array_slice($out,0,20);}
    public static function makeSlug(string $name,int $userId): string{$map=['İ'=>'i','I'=>'i','ı'=>'i','Ş'=>'s','ş'=>'s','Ğ'=>'g','ğ'=>'g','Ü'=>'u','ü'=>'u','Ö'=>'o','ö'=>'o','Ç'=>'c','ç'=>'c'];$slug=strtolower(strtr(trim($name),$map));$slug=preg_replace('/[^a-z0-9]+/','-',$slug)??'';$slug=trim($slug,'-');if($slug==='')$slug='teknik-direktor';return substr($slug,0,135).'-'.$userId;}
    public static function save(int $userId,array $data,array $careerRows,bool $submit): int
    {
        $errors=self::validateInput($data)+CoachCareerEntry::validateRows($careerRows);if($errors!==[])throw new RuntimeException((string)reset($errors));$identity=User::profileIdentity($userId);if(!$identity||($identity['status']??'')!=='active')throw new RuntimeException('Aktif kullanıcı hesabı bulunamadı.');FootballIdentity::syncForUser($userId,['coach'],'coach');$existing=self::forOwner($userId);$slug=$existing['slug']??self::makeSlug((string)$identity['display_name'],$userId);$status=$submit?'pending':'draft';$params=['user_id'=>$userId,'slug'=>$slug,'public_title'=>trim((string)($data['public_title']??'Teknik Direktör')),'province'=>TurkeyLocation::canonicalProvince((string)$data['province'])??trim((string)$data['province']),'district'=>TurkeyLocation::canonicalDistrict((string)$data['province'],(string)$data['district'])??trim((string)$data['district']),'license_level'=>self::nullEmpty($data['license_level']??null),'intent'=>(string)($data['intent']??'showcase'),'specialties_json'=>json_encode(self::normalizeList($data['specialties']??[]),JSON_UNESCAPED_UNICODE),'formations_json'=>json_encode(self::normalizeList($data['formations']??[]),JSON_UNESCAPED_UNICODE),'bio'=>self::nullEmpty($data['bio']??null),'achievements_text'=>self::nullEmpty($data['achievements_text']??null),'status'=>$status];$pdo=Database::connection();$pdo->beginTransaction();try{if($existing){$params['id']=(int)$existing['id'];$sql='UPDATE coach_profiles SET slug=:slug,public_title=:public_title,province=:province,district=:district,license_level=:license_level,intent=:intent,specialties_json=:specialties_json,formations_json=:formations_json,bio=:bio,achievements_text=:achievements_text,status=:status,moderation_note=NULL,updated_at=NOW() WHERE id=:id AND user_id=:user_id';}else{$sql='INSERT INTO coach_profiles (user_id,slug,public_title,province,district,license_level,intent,specialties_json,formations_json,bio,achievements_text,status) VALUES (:user_id,:slug,:public_title,:province,:district,:license_level,:intent,:specialties_json,:formations_json,:bio,:achievements_text,:status)';}$st=$pdo->prepare($sql);$st->execute($params);$id=$existing?(int)$existing['id']:(int)$pdo->lastInsertId();CoachCareerEntry::replaceForProfile($id,$careerRows);$pdo->commit();FootballIdentity::setStatus($userId,'coach',$submit?'pending':'draft',false);return$id;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}
    }
    public static function forOwner(int $userId): ?array{$s=Database::connection()->prepare('SELECT c.*,u.display_name,u.username,u.profile_verified_at,p.avatar_path FROM coach_profiles c INNER JOIN users u ON u.id=c.user_id LEFT JOIN player_profiles p ON p.user_id=u.id WHERE c.user_id=:user_id LIMIT 1');$s->execute(['user_id'=>$userId]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($r))return null;$r=self::hydrate($r);$r['career']=CoachCareerEntry::forProfile((int)$r['id']);return$r;}
    public static function findPublicBySlug(string $slug): ?array{$s=Database::connection()->prepare('SELECT c.*,u.display_name,u.username,u.profile_verified_at,p.avatar_path FROM coach_profiles c INNER JOIN users u ON u.id=c.user_id LEFT JOIN player_profiles p ON p.user_id=u.id WHERE c.slug=:slug AND c.status="active" AND u.status="active" LIMIT 1');$s->execute(['slug'=>$slug]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($r))return null;$r=self::hydrate($r);$r['career']=CoachCareerEntry::forProfile((int)$r['id']);return$r;}
    public static function search(array $filters=[],int $limit=48): array{$limit=max(1,min(100,$limit));$sql='SELECT c.*,u.display_name,u.username,u.profile_verified_at,p.avatar_path FROM coach_profiles c INNER JOIN users u ON u.id=c.user_id LEFT JOIN player_profiles p ON p.user_id=u.id WHERE c.status="active" AND u.status="active"';$params=[];foreach(['province','district','intent'] as $key){$v=trim((string)($filters[$key]??''));if($v!==''){$sql.=' AND c.'.$key.'=:'.$key;$params[$key]=$v;}}$title=trim((string)($filters['public_title']??''));if($title!==''){$sql.=' AND c.public_title LIKE :title';$params['title']='%'.$title.'%';}$license=trim((string)($filters['license_level']??''));if($license!==''){$sql.=' AND c.license_level LIKE :license';$params['license']='%'.$license.'%';}if(!empty($filters['verified']))$sql.=' AND c.license_status="verified"';$spec=trim((string)($filters['specialty']??''));if($spec!==''){$sql.=' AND c.specialties_json LIKE :spec';$params['spec']='%'.$spec.'%';}$sql.=' ORDER BY (c.license_status="verified") DESC,(c.intent="open_to_offers") DESC,c.updated_at DESC LIMIT '.$limit;$s=Database::connection()->prepare($sql);$s->execute($params);$rows=$s->fetchAll(PDO::FETCH_ASSOC)?:[];return array_map([self::class,'hydrate'],$rows);}

    public static function activeForUser(int $userId): ?array{$s=Database::connection()->prepare('SELECT c.*,u.display_name,u.username FROM coach_profiles c INNER JOIN users u ON u.id=c.user_id WHERE c.user_id=:user_id AND c.status="active" AND u.status="active" LIMIT 1');$s->execute(['user_id'=>$userId]);$r=$s->fetch(PDO::FETCH_ASSOC);return is_array($r)?self::hydrate($r):null;}
    public static function adminList(int $limit=100): array{$limit=max(1,min(200,$limit));$rows=Database::connection()->query('SELECT c.*,u.display_name,u.username FROM coach_profiles c INNER JOIN users u ON u.id=c.user_id ORDER BY c.updated_at DESC LIMIT '.$limit)->fetchAll(PDO::FETCH_ASSOC)?:[];return array_map([self::class,'hydrate'],$rows);}
    public static function adminFind(int $id): ?array{$s=Database::connection()->prepare('SELECT c.*,u.display_name,u.username,u.email,u.phone FROM coach_profiles c INNER JOIN users u ON u.id=c.user_id WHERE c.id=:id LIMIT 1');$s->execute(['id'=>$id]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($r))return null;$r=self::hydrate($r);$r['career']=CoachCareerEntry::forProfile($id);return$r;}
    public static function setAdminStatus(int $id,string $status,?string $note=null): bool{if(!in_array($status,['active','suspended','rejected','pending'],true))return false;$s=Database::connection()->prepare('UPDATE coach_profiles SET status=:status,moderation_note=:note,published_at=CASE WHEN :status2="active" THEN COALESCE(published_at,NOW()) ELSE published_at END,updated_at=NOW() WHERE id=:id');$s->execute(['status'=>$status,'note'=>self::nullEmpty($note),'status2'=>$status,'id'=>$id]);$p=self::adminFind($id);if($p)FootballIdentity::setStatus((int)$p['user_id'],'coach',$status==='active'?'active':($status==='suspended'?'suspended':'pending'),$status==='active');return true;}
    public static function setLicenseStatus(int $id,string $status,int $adminId): bool{if(!in_array($status,['unverified','verified','rejected'],true)||$adminId<=0)return false;$s=Database::connection()->prepare('UPDATE coach_profiles SET license_status=:status,license_verified_by_admin_id=CASE WHEN :status2="verified" THEN :admin ELSE NULL END,license_verified_at=CASE WHEN :status3="verified" THEN NOW() ELSE NULL END,updated_at=NOW() WHERE id=:id');return$s->execute(['status'=>$status,'status2'=>$status,'status3'=>$status,'admin'=>$adminId,'id'=>$id]);}
    public static function hydrate(array $row): array{$row['specialties']=self::decode($row['specialties_json']??null);$row['formations']=self::decode($row['formations_json']??null);return$row;}
    private static function decode(mixed $v): array{$d=json_decode((string)$v,true);return is_array($d)?array_values(array_filter(array_map('strval',$d))):[];}
    private static function nullEmpty(mixed $v): ?string{$v=trim((string)$v);return$v===''?null:$v;}
    private static function length(string $v): int{return function_exists('mb_strlen')?mb_strlen($v,'UTF-8'):strlen($v);}
